window.remountProbe = (() => {
 const view = document.querySelector('.cm-content').cmTile.root.view;
 const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
 let active = null, frame = null, lastFrame = 0;
 const rows = [], ids = new WeakMap(); let nextID = 0;
 const svgID = svg => { if (!ids.has(svg)) ids.set(svg, ++nextID); return ids.get(svg); };
 const inner = Object.getOwnPropertyDescriptor(Element.prototype, 'innerHTML');
 const bounds = Element.prototype.getBoundingClientRect;
 const create = Document.prototype.createElement;
 Document.prototype.createElement=function(name,...args){if(active&&name.toLowerCase()==='img')active.imageCreates++;return create.call(this,name,...args);};
 const mathRender=window.katex.render;window.katex.render=function(...args){if(active)active.mathRenders++;return mathRender.apply(this,args);};
 Object.defineProperty(Element.prototype, 'innerHTML', {...inner, set(value) {
  if (active) active.markupWrites++;
  return inner.set.call(this, value);
 }});
 Element.prototype.getBoundingClientRect = function(...args) {
  if (active && this.classList?.contains('cm-source-footprint-sizer')) active.rulerReads++;
  return bounds.apply(this,args);
 };
 const keyBegin = event => {
  if (!active || !['ArrowDown','ArrowUp'].includes(event.key)) return;
  active.keys.push({key:event.key,repeat:event.repeat,start:performance.now(),before:view.state.selection.main.head});
 };
 const keyEnd = event => {
  if (!active || !['ArrowDown','ArrowUp'].includes(event.key)) return;
  const key=active.keys.at(-1);if(key){key.end=performance.now();key.after=view.state.selection.main.head;}
 };
 document.addEventListener('keydown',keyBegin,true);window.addEventListener('keydown',keyEnd);
 const tick = now => {if(active){active.frames.push(now-lastFrame);lastFrame=now;}frame=requestAnimationFrame(tick);};frame=requestAnimationFrame(tick);
 function select(at) {view.dispatch({selection:{anchor:at},effects:view.constructor.scrollIntoView(at,{y:'center'})});view.focus();}
 function fixture(kind) {
  let text='# Native retained previews\n\n';
  for(let i=0;i<12;i++){
   const code=Array.from({length:12},(_,n)=>`const item${n} = {name: "Row ${i}-${n}", value: Math.max(${n}, ${i})};`).join('\n');
   const math='\\begin{aligned}\n'+Array.from({length:5},(_,n)=>`f_{${n}}(x) &= \\frac{x^{${n+1}} + \\sqrt{${i+1}}}{1+x^2}`).join(' '+String.fromCharCode(92,92)+'\n')+'\n\\end{aligned}';
   const table='| Name | Description | Count |\n| --- | --- | ---: |\n'+Array.from({length:12},(_,n)=>`| **Row ${i}-${n}** | Item with text | ${n*3} |`).join('\n');
   const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="800" height="260" viewBox="0 0 800 260"><rect width="800" height="260" fill="#345777"/>${Array.from({length:36},(_,n)=>`<circle cx="${20+n%12*66}" cy="${40+Math.floor(n/12)*80}" r="18" fill="hsl(${(n*19+i*11)%360} 65% 65%)"/>`).join('')}</svg>`;
   const block=kind==='code'?'```js\n'+code+'\n```':kind==='math'?'$$\n'+math+'\n$$':kind==='table'?table:'![Native image '+i+'](data:image/svg+xml;base64,'+btoa(svg)+')';
   text+='## Block '+i+'\n\nBefore block '+i+'.\n\n'+block+'\n\nAfter block '+i+'.\n\nPlain paragraph for navigation '+i+'.\n\n';
  }
  return text+'End of the measured document.\n';
 }
 const api = {view,rows,done:false,error:null,source:'',kind:'',
  prepare(kind){api.done=false;api.error=null;(async()=>{
   api.kind=kind;api.source=fixture(kind);view.dispatch({changes:{from:0,to:view.state.doc.length,insert:api.source},selection:{anchor:0}});view.focus();await wait(500);
   // Visit every block while quiet so return navigation measures prepared output.
   for(let i=0;i<12;i++){select(api.source.indexOf('Before block '+i));await wait(400);}
   select(0);await wait(500);
  })().catch(e=>api.error=String(e.stack||e)).finally(()=>api.done=true);},
  start(label){lastFrame=performance.now();active={kind:api.kind,label,keys:[],frames:[],markupWrites:0,imageCreates:0,mathRenders:0,rulerReads:0,started:lastFrame};},
  stop(){const row=active;active=null;row.elapsed=performance.now()-row.started;row.sourceIntact=view.state.doc.toString()===api.source;rows.push(row);return row;},
  remount(){api.done=false;api.error=null;(async()=>{
   const before=api.source.indexOf('Before block 0');
   const startBlock=api.source.indexOf('\n\n',before)+2,inside=startBlock+3;
   const selector={code:'.cm-codeblock-widget code',math:'.cm-math-block .cm-source-footprint-graphic',table:'.cm-live-table table',image:'.cm-image-widget img'}[api.kind];
   const rootSelector={code:'.cm-codeblock-widget',math:'.cm-math-block',table:'.cm-block-widget--table',image:'.cm-image-widget'}[api.kind];
   const targetSVG=()=>[...view.dom.querySelectorAll(selector)].find(node=>view.posAtDOM(node.closest(rootSelector),0)===startBlock)||null;
   select(before);await wait(500);
   api.start('warm_source_preview_switch');
   active.switches=[];
   for(let i=0;i<8;i++){
    const previous=targetSVG();
    const prior=previous?svgID(previous):null;
    select(inside);await wait(50);const start=performance.now();select(before);
    let graphic=null;for(let n=0;n<100;n++){graphic=targetSVG();if(graphic)break;await wait(5);}
    active.switches.push({ms:performance.now()-start,sameSVG:graphic?svgID(graphic)===prior:null});await wait(160);
   }
   api.stop();select(0);await wait(300);
  })().catch(e=>api.error=String(e.stack||e)).finally(()=>api.done=true);},
  dispose(){if(frame!==null)cancelAnimationFrame(frame);Document.prototype.createElement=create;window.katex.render=mathRender;document.removeEventListener('keydown',keyBegin,true);window.removeEventListener('keydown',keyEnd);Object.defineProperty(Element.prototype,'innerHTML',inner);Element.prototype.getBoundingClientRect=bounds;},
 };return api;
})();true;
